macro_rules! deps {
    () => {
        StateID!();
        NFA!();
        Builder!();
        State!();
        Match!();
        GroupInfo!();
        LookSet!();
        ByteClasses!();
        ByteClassSet!();
        LookMatcher!();
    };
}

macro_rules! Inner {
    () => {
        deps!();
        # [doc = " The \"inner\" part of the NFA. We split this part out so that we can easily"] # [doc = " wrap it in an `Arc` above in the definition of `NFA`."] # [doc = ""] # [doc = " See builder.rs for the code that actually builds this type. This module"] # [doc = " does provide (internal) mutable methods for adding things to this"] # [doc = " NFA before finalizing it, but the high level construction process is"] # [doc = " controlled by the builder abstraction. (Which is complicated enough to"] # [doc = " get its own module.)"] # [derive (Default)] pub (super) struct Inner { # [doc = " The state sequence. This sequence is guaranteed to be indexable by all"] # [doc = " starting state IDs, and it is also guaranteed to contain at most one"] # [doc = " `Match` state for each pattern compiled into this NFA. (A pattern may"] # [doc = " not have a corresponding `Match` state if a `Match` state is impossible"] # [doc = " to reach.)"] states : Vec < State > , # [doc = " The anchored starting state of this NFA."] start_anchored : StateID , # [doc = " The unanchored starting state of this NFA."] start_unanchored : StateID , # [doc = " The starting states for each individual pattern. Starting at any"] # [doc = " of these states will result in only an anchored search for the"] # [doc = " corresponding pattern. The vec is indexed by pattern ID. When the NFA"] # [doc = " contains a single regex, then `start_pattern[0]` and `start_anchored`"] # [doc = " are always equivalent."] start_pattern : Vec < StateID > , # [doc = " Info about the capturing groups in this NFA. This is responsible for"] # [doc = " mapping groups to slots, mapping groups to names and names to groups."] group_info : GroupInfo , # [doc = " A representation of equivalence classes over the transitions in this"] # [doc = " NFA. Two bytes in the same equivalence class must not discriminate"] # [doc = " between a match or a non-match. This map can be used to shrink the"] # [doc = " total size of a DFA's transition table with a small match-time cost."] # [doc = ""] # [doc = " Note that the NFA's transitions are *not* defined in terms of these"] # [doc = " equivalence classes. The NFA's transitions are defined on the original"] # [doc = " byte values. For the most part, this is because they wouldn't really"] # [doc = " help the NFA much since the NFA already uses a sparse representation"] # [doc = " to represent transitions. Byte classes are most effective in a dense"] # [doc = " representation."] byte_class_set : ByteClassSet , # [doc = " This is generated from `byte_class_set`, and essentially represents the"] # [doc = " same thing but supports different access patterns. Namely, this permits"] # [doc = " looking up the equivalence class of a byte very cheaply."] # [doc = ""] # [doc = " Ideally we would just store this, but because of annoying code"] # [doc = " structure reasons, we keep both this and `byte_class_set` around for"] # [doc = " now. I think I would prefer that `byte_class_set` were computed in the"] # [doc = " `Builder`, but right now, we compute it as states are added to the"] # [doc = " `NFA`."] byte_classes : ByteClasses , # [doc = " Whether this NFA has a `Capture` state anywhere."] has_capture : bool , # [doc = " When the empty string is in the language matched by this NFA."] has_empty : bool , # [doc = " Whether UTF-8 mode is enabled for this NFA. Briefly, this means that"] # [doc = " all non-empty matches produced by this NFA correspond to spans of valid"] # [doc = " UTF-8, and any empty matches produced by this NFA that split a UTF-8"] # [doc = " encoded codepoint should be filtered out by the corresponding regex"] # [doc = " engine."] utf8 : bool , # [doc = " Whether this NFA is meant to be matched in reverse or not."] reverse : bool , # [doc = " The matcher to be used for look-around assertions."] look_matcher : LookMatcher , # [doc = " The union of all look-around assertions that occur anywhere within"] # [doc = " this NFA. If this set is empty, then it means there are precisely zero"] # [doc = " conditional epsilon transitions in the NFA."] look_set_any : LookSet , # [doc = " The union of all look-around assertions that occur as a zero-length"] # [doc = " prefix for any of the patterns in this NFA."] look_set_prefix_any : LookSet , # [doc = " Heap memory used indirectly by NFA states and other things (like the"] # [doc = " various capturing group representations above). Since each state"] # [doc = " might use a different amount of heap, we need to keep track of this"] # [doc = " incrementally."] memory_extra : usize , }
    };
}

Inner!();